<script setup lang="ts">
const api = useApi(), auth = useAuth()
const data = ref<any>(null), loading = ref(true), busy = ref(''), error = ref(''), notice = ref(''), conflict = ref(false)
const diagnostics = ref<any>(null), checking = ref(false), dnsError = ref('')
const setup = reactive({ revision: 0, provider: 'postal', enabled: false, sender_name: 'CardShelf', from_address: 'noreply@cardshelf.cloud', reply_to: '', api_key: '', clear_api_key: false, dkim_selector: '', dkim_public_key: '', webhook_public_key: '', password: '', smtp_preset: 'custom', smtp_host: '', smtp_port: 587, smtp_security: 'starttls', smtp_user: '', smtp_password: '', clear_smtp_password: false, smtp_rate_limit: 10 })
const testPassword = ref(''), connectionPassword = ref(''), retryPassword = ref(''), retryItem = ref<any>(null)
const suppression = reactive({ email: '', reason: '', suppressed: true, password: '' })
let alive = true
const isAdmin = computed(() => auth.state.value.user?.role === 'admin')
const providerName = computed(() => data.value?.settings.provider === 'smtp' ? data.value?.settings.smtp_preset === 'wpmu' ? 'WPMU DEV Basic SMTP' : data.value?.settings.smtp_host === 'mail.mailconfig.net' ? 'WPMU DEV Pro SMTP' : 'External SMTP' : 'Postal')
const postalConsole = computed(() => { try { const url = new URL(data.value?.settings?.origin); return url.protocol === 'https:' && !url.username && !url.password ? url.origin : '' } catch { return '' } })
const statusLabels: Record<string, string> = { queued: 'Queued', processing: 'Processing', sending: 'Sending', accepted: 'Accepted by mail service', sent: 'Accepted by mail server', delivered: 'Delivered to receiving server', failed: 'Failed', uncertain: 'Delivery uncertain', bounced: 'Bounced', held: 'Held', suppressed: 'Suppressed', cancelled: 'Cancelled', expired: 'Expired' }
const kindLabels: Record<string, string> = { verify: 'Email verification', password_reset: 'Password recovery', password_recovery: 'Password recovery', recovery: 'Password recovery', test: 'Test email', marketplace_enquiry: 'Marketplace enquiry', marketplace_reply: 'Marketplace reply', tier_change: 'Membership update', membership_changed: 'Membership update', password_changed: 'Password changed', reset: 'Password recovery', changed: 'Password changed' }
const checkLabels: Record<string, string> = { pass: 'Check passed', warn: 'Review needed', fail: 'Check failed', unknown: 'Could not check' }
const date = (value: any) => value && Number.isFinite(new Date(value).getTime()) ? new Date(value).toLocaleString() : 'Not available'
function acceptSettings(settings: any) {
  setup.revision = settings.revision; setup.enabled = !!settings.enabled; setup.sender_name = settings.sender_name || 'CardShelf'; setup.from_address = settings.from_address || 'noreply@cardshelf.cloud'; setup.reply_to = settings.reply_to || ''; setup.dkim_selector = settings.dkim_selector || ''; setup.dkim_public_key = settings.dkim_public_key || ''; setup.webhook_public_key = settings.webhook_public_key || ''
  setup.provider = settings.provider || 'postal'; setup.smtp_preset = settings.smtp_preset || 'custom'; setup.smtp_host = settings.smtp_host || ''; setup.smtp_port = settings.smtp_port || 587; setup.smtp_security = settings.smtp_security || 'starttls'; setup.smtp_user = settings.smtp_user || ''; setup.smtp_rate_limit = settings.smtp_rate_limit || 10
  setup.api_key = ''; setup.clear_api_key = false; setup.smtp_password = ''; setup.clear_smtp_password = false; setup.password = ''; connectionPassword.value = ''; conflict.value = false
}
function selectProvider() { setup.api_key = ''; setup.smtp_password = ''; setup.clear_api_key = false; setup.clear_smtp_password = false; connectionPassword.value = '' }
function applySmtpPreset() {
  if (setup.smtp_preset === 'wpmu') { setup.smtp_host = 'mailu.wpmudev.host'; setup.smtp_port = 587; setup.smtp_security = 'starttls'; setup.smtp_rate_limit = Math.min(setup.smtp_rate_limit, 10); if (!setup.smtp_user) setup.smtp_user = setup.from_address }
  if (setup.smtp_preset === 'wpmu_pro') { if (setup.smtp_host !== 'mail.mailconfig.net') { setup.smtp_host = 'mail.mailconfig.net'; setup.smtp_port = 465; setup.smtp_security = 'tls' }; if (!setup.smtp_user) setup.smtp_user = setup.from_address }
  setup.smtp_password = ''; setup.clear_smtp_password = false
}
function selectSmtpSecurity() { setup.smtp_port = setup.smtp_security === 'tls' ? 465 : 587 }
async function load(syncSettings = true) {
  if (!isAdmin.value) { loading.value = false; return }
  loading.value = true; error.value = ''
  try { const result = await api('/api/admin/emails'); if (alive) { data.value = result; if (syncSettings) acceptSettings(result.settings) } }
  catch (e) { if (alive) error.value = errorMessage(e) }
  finally { if (alive) loading.value = false }
}
async function mutate(action: string, body: any, fallback: string) {
  if (busy.value || !isAdmin.value || !body.password) return false
  busy.value = action; error.value = ''; notice.value = ''
  try { const result = await api('/api/admin/emails/' + action, { method: 'POST', body }); if (!alive) return false; if (action === 'settings') { acceptSettings(result); diagnostics.value = null } notice.value = result.message || fallback; await load(false); return true }
  catch (e: any) { if (alive) { error.value = errorMessage(e); if (action === 'settings' && (e?.statusCode || e?.status) === 409 && /settings changed/i.test(error.value)) { conflict.value = true; error.value += ' Reload the saved settings before applying another change.' } else if (action === 'connection') error.value += ' This connection check did not send an email.'; else if (![400, 401, 403, 404, 409, 422, 429].includes(e?.statusCode || e?.status)) error.value += ' Check the delivery history before repeating this action.' } return false }
  finally { busy.value = ''; setup.password = ''; testPassword.value = ''; connectionPassword.value = ''; retryPassword.value = ''; suppression.password = ''; if (action === 'settings') { setup.api_key = ''; setup.smtp_password = '' } }
}
async function save() {
  if (!data.value || conflict.value || loading.value) return
  await mutate('settings', { ...setup, api_key: setup.clear_api_key ? '' : setup.api_key, smtp_password: setup.clear_smtp_password ? '' : setup.smtp_password }, 'Email settings saved.')
}
async function sendTest() { await mutate('test', { password: testPassword.value }, 'Test email queued to your account.') }
async function checkConnection() {
  if (!data.value || data.value.settings.provider !== 'smtp' || !data.value.settings.configured) return
  await mutate('connection', { password: connectionPassword.value, revision: data.value.settings.revision }, 'SMTP connection checked.')
}
function selectRetry(row: any) { if (!row.can_retry || busy.value) return; retryItem.value = row; retryPassword.value = '' }
async function retry() {
  if (!retryItem.value || !data.value?.recent.some((row: any) => row.id === retryItem.value.id && row.can_retry)) return
  if (await mutate('retry', { id: retryItem.value.id, password: retryPassword.value }, 'Notification queued for another delivery attempt.')) retryItem.value = null
}
function reviewSuppression(row: any) { if (busy.value) return; suppression.email = row.email; suppression.reason = ''; suppression.suppressed = false; suppression.password = ''; nextTick(() => document.getElementById('suppression-email')?.focus()) }
async function saveSuppression() { if (await mutate('suppressions', { ...suppression }, suppression.suppressed ? 'Recipient suppressed.' : 'Recipient suppression removed.')) { suppression.email = ''; suppression.reason = ''; suppression.suppressed = true } }
async function checkDns() {
  if (checking.value || !data.value || !isAdmin.value) return
  checking.value = true; dnsError.value = ''
  try { const result = await api('/api/admin/emails/diagnostics'); if (alive) diagnostics.value = result }
  catch (e) { if (alive) dnsError.value = errorMessage(e) }
  finally { if (alive) checking.value = false }
}
onMounted(() => { void load() })
onBeforeUnmount(() => { alive = false; setup.api_key = ''; setup.smtp_password = ''; setup.password = ''; testPassword.value = ''; connectionPassword.value = ''; retryPassword.value = ''; suppression.password = ''; data.value = null })
useSeoMeta({ title: 'Email administration · CardShelf', robots: 'noindex, nofollow' })
</script>
<template>
  <main class="emails-admin">
    <header class="page-heading"><div><span class="eyebrow">MORE · ADMINISTRATION</span><h1>Emails</h1><p>Manage CardShelf’s email connection, delivery and recipients from one place.</p></div><div class="button-row"><NuxtLink to="/emails" class="button secondary">My preferences</NuxtLink><NuxtLink to="/admin/passwords" class="button secondary">Password recovery</NuxtLink></div></header>
    <p v-if="!isAdmin" class="alert error" role="alert">Administrator access is required.</p>
    <p v-if="error" class="alert error" role="alert">{{ error }}</p><p v-if="notice" class="alert info" role="status">{{ notice }}</p>
    <p v-if="loading && !data" class="loading-panel" role="status">Loading email administration…</p>
    <template v-if="data && isAdmin">
      <nav class="email-section-nav" aria-label="Email administration sections"><a href="#email-connection">Connection</a><a href="#email-setup">Provider setup</a><a href="#email-diagnostics">DNS checks</a><a href="#email-delivery">Delivery</a><a href="#email-suppressions">Suppressions</a><button class="text-button" :disabled="!!busy || loading" @click="load(false)">Refresh status</button></nav>
      <section class="email-summary-grid" aria-label="Email connection status"><div class="panel"><span>{{ providerName }} sending</span><strong>{{ !data.settings.exists ? 'Not configured' : data.settings.enabled ? 'Enabled' : 'Paused' }}</strong><small>{{ data.settings.configured ? 'Saved connection configured' : 'Connection needs setup' }}</small></div><div class="panel"><span>Sending credential</span><strong>{{ (data.settings.provider === 'smtp' ? data.settings.smtp_password_set : data.settings.api_key_set) ? 'Stored' : 'Not set' }}</strong><small>Credentials are never shown after saving.</small></div><div class="panel"><span>Sending domain</span><strong>cardshelf.cloud</strong><small>{{ data.settings.from_address || 'Choose a sender address below.' }}</small></div></section>
      <section id="email-connection" class="panel email-panel"><div class="section-heading"><div><h2>Email connection</h2><p>Your sender identity and delivery controls.</p></div><a v-if="setup.provider === 'postal' && postalConsole" :href="postalConsole" target="_blank" rel="noopener noreferrer" class="button secondary">Open Postal console ↗</a></div>
        <p v-if="data.settings.config_error" class="alert error" role="status">{{ data.settings.config_error }}</p><p v-if="!data.settings.key_available" class="alert warning">Credential storage is not ready on this server. Complete the one-time integration encryption setup before saving a mail credential.</p>
        <p v-if="data.settings.worker_enabled === false" class="alert warning">The email delivery worker is paused in this deployment. Queued messages will wait until the server operator starts it.</p><p v-if="setup.provider === 'postal'" class="email-provider-note">Postal server: <code>{{ data.settings.origin || 'Not configured' }}</code>. This address is controlled by the server deployment.</p>
        <form class="form-stack" @submit.prevent="save"><fieldset :disabled="!!busy || loading" class="email-fieldset"><div class="email-form-grid"><label for="email-provider">Email provider<select id="email-provider" v-model="setup.provider" @change="selectProvider"><option value="postal">Postal API</option><option value="smtp">External SMTP (WPMU DEV or another service)</option></select><small>Recovery, security and opted-in notifications use this provider.</small></label><label for="email-sender-name">Sender name<input id="email-sender-name" v-model="setup.sender_name" required maxlength="80" autocomplete="organization" placeholder="CardShelf"></label><label for="email-from">Sender address<input id="email-from" v-model="setup.from_address" type="email" required maxlength="254" autocomplete="off" placeholder="noreply@cardshelf.cloud"><small>Use a verified cardshelf.cloud address.</small></label><label for="email-reply">Reply-to address<input id="email-reply" v-model="setup.reply_to" type="email" maxlength="254" autocomplete="off" placeholder="support@cardshelf.cloud"><small>Optional. Use a monitored cardshelf.cloud address for replies.</small></label><label v-if="setup.provider === 'postal'" for="postal-api-key">{{ data.settings.api_key_set ? 'Replace Postal API credential' : 'Postal API credential' }}<input id="postal-api-key" v-model="setup.api_key" type="password" autocomplete="off" spellcheck="false" maxlength="512" :disabled="setup.clear_api_key || !data.settings.key_available" :placeholder="data.settings.api_key_set ? 'Leave blank to retain stored credential' : 'Paste the server’s Postal API credential'"><small>{{ data.settings.api_key_set ? 'Blank retains the current credential. A replacement is encrypted before storage.' : 'Create an API credential for this mail server in Postal.' }}</small></label></div>
          <div v-if="setup.provider === 'smtp'" class="email-form-grid">
            <label for="smtp-preset">SMTP service<select id="smtp-preset" v-model="setup.smtp_preset" @change="applySmtpPreset"><option value="custom">Custom SMTP service</option><option value="wpmu">WPMU DEV Basic Email</option><option value="wpmu_pro">WPMU DEV Pro Email</option></select></label>
            <label for="smtp-host">SMTP hostname<input id="smtp-host" v-model="setup.smtp_host" required maxlength="253" autocomplete="off" spellcheck="false" :readonly="setup.smtp_preset !== 'custom'" placeholder="smtp.your-provider.com"><small>Use your provider’s public outgoing-mail hostname.</small></label>
            <label for="smtp-security">SMTP encryption<select id="smtp-security" v-model="setup.smtp_security" :disabled="setup.smtp_preset === 'wpmu'" @change="selectSmtpSecurity"><option value="starttls">Required STARTTLS · port 587</option><option value="tls">TLS · port 465</option></select><small>Certificates are verified. Unencrypted sending is unavailable.</small></label>
            <label for="smtp-user">SMTP username<input id="smtp-user" v-model="setup.smtp_user" required maxlength="320" autocomplete="off" spellcheck="false" placeholder="noreply@cardshelf.cloud"><small>WPMU DEV uses the full mailbox email address.</small></label>
            <label for="smtp-password">{{ data.settings.smtp_password_set ? 'Replace SMTP password' : 'SMTP password' }}<input id="smtp-password" v-model="setup.smtp_password" type="password" maxlength="4096" autocomplete="off" spellcheck="false" :disabled="setup.clear_smtp_password || !data.settings.key_available" :placeholder="data.settings.smtp_password_set ? 'Leave blank to retain the saved password' : 'Mailbox password or provider app password'"><small>Encrypted after saving. Enter it again when changing the server or username.</small></label>
            <label for="smtp-rate">Maximum emails per minute<input id="smtp-rate" v-model.number="setup.smtp_rate_limit" type="number" min="1" :max="setup.smtp_preset === 'wpmu' ? 10 : 60" required><small>Shared by recovery and activity emails. Allow capacity for other apps using the same service.</small></label>
          </div>
          <label class="checkbox-label email-check"><input v-model="setup.enabled" type="checkbox" :disabled="setup.provider === 'smtp' ? setup.clear_smtp_password : setup.clear_api_key">Enable CardShelf email</label><label v-if="setup.provider === 'postal' && data.settings.api_key_set" class="checkbox-label email-check"><input v-model="setup.clear_api_key" type="checkbox">Remove the saved API credential and pause email sending</label>
          <label v-if="setup.provider === 'smtp' && data.settings.smtp_password_set" class="checkbox-label email-check"><input v-model="setup.clear_smtp_password" type="checkbox">Remove the saved SMTP password and pause SMTP sending</label><details class="email-advanced"><summary>Domain signing and webhook verification</summary><p class="small muted">Copy the public DKIM selector and TXT record supplied by your selected mail provider. Postal also needs its webhook verification key.</p><div class="email-form-grid"><label for="email-dkim-selector">DKIM selector<input id="email-dkim-selector" v-model="setup.dkim_selector" maxlength="63" autocomplete="off" spellcheck="false" placeholder="Selector shown by your mail provider"></label><label for="email-dkim-key">DKIM public TXT value<textarea id="email-dkim-key" v-model="setup.dkim_public_key" maxlength="4000" rows="4" autocomplete="off" spellcheck="false" placeholder="v=DKIM1; k=rsa; p=…"></textarea><small>Optional reference for DNS comparison. Paste the complete public TXT value on one line, starting with v=DKIM1. Never paste a private key.</small></label></div><label v-if="setup.provider === 'postal'" for="email-webhook-key">Postal webhook verification public key (RSA PEM)<textarea id="email-webhook-key" v-model="setup.webhook_public_key" maxlength="8000" rows="5" autocomplete="off" spellcheck="false" placeholder="-----BEGIN PUBLIC KEY-----"></textarea><small>Use the Postal installation’s HTTP signing public key in RSA PEM format (2048 bits or stronger). This is separate from the domain’s DKIM public key and API credential.</small></label></details>
          <div class="email-confirmation"><label for="email-admin-password">Administrator password<input id="email-admin-password" v-model="setup.password" type="password" required autocomplete="current-password" maxlength="128"></label><div class="button-row"><button class="button primary" :disabled="!setup.password || conflict || (!data.settings.key_available && ((setup.enabled && !(setup.provider === 'smtp' ? setup.clear_smtp_password : setup.clear_api_key)) || !!setup.api_key || !!setup.smtp_password))">{{ busy === 'settings' ? 'Saving…' : 'Save email settings' }}</button><button v-if="conflict" type="button" class="button secondary" @click="load(true)">Reload saved settings</button></div></div>
        </fieldset></form>
      </section>
      <section v-if="setup.provider === 'smtp'" id="email-setup" class="panel email-panel"><h2>External SMTP setup</h2><ol class="email-setup-list"><li>Provision a sending mailbox or SMTP service for <strong>cardshelf.cloud</strong>. Publish the sender records provided by that service.</li><li>Select the matching WPMU DEV Basic or Pro preset, or enter another provider’s SMTP settings. Use an authorized sender address, then save the connection.</li><li>Check the saved connection, enable email and send a test to your own administrator account. Inspect the inbox and message headers for sender signing.</li></ol><p v-if="setup.smtp_preset === 'wpmu'" class="data-note">WPMU DEV’s free basic mailboxes require a WPMU DEV hosted site. The sending limit is 10 messages per minute per source IP. CardShelf uses SMTP for outgoing messages; retrieve mailbox replies and bounces with your mail client. <a href="https://wpmudev.com/docs/hosting/emails/" target="_blank" rel="noopener noreferrer">WPMU DEV setup guide ↗</a></p><p v-if="setup.smtp_preset === 'wpmu_pro' || setup.smtp_host === 'mail.mailconfig.net'" class="data-note">Pro Email is a separate paid service. Use mail.mailconfig.net with TLS on port 465 or required STARTTLS on port 587 and the full mailbox address. New accounts start at approximately 25 emails per rolling 24 hours, rising to 500 after about two weeks. Check the Hub’s current account allowance; the per-minute setting does not enforce this daily quota. <a href="https://wpmudev.com/docs/hub-2-0/pro-email/" target="_blank" rel="noopener noreferrer">WPMU DEV Pro Email guide ↗</a></p><p class="data-note">A successful connection check verifies TLS and login. SMTP acceptance does not confirm inbox delivery; review bounces with your provider and add suppressions below when needed.</p>
        <form class="email-test-form" @submit.prevent="checkConnection"><div><h3>Check saved SMTP connection</h3><p class="small muted">No email is sent. Save any edits before checking.</p><p v-if="data.settings.smtp_verified_at" class="small muted">Last successful check: {{ date(data.settings.smtp_verified_at) }}</p></div><label for="connection-admin-password">Administrator password for connection check<input id="connection-admin-password" v-model="connectionPassword" type="password" required autocomplete="current-password" maxlength="128" :disabled="!!busy"></label><button class="button secondary" :disabled="!!busy || !connectionPassword || data.settings.provider !== 'smtp' || !data.settings.configured">{{ busy === 'connection' ? 'Checking connection…' : 'Check SMTP connection' }}</button></form>
      </section><section v-else id="email-setup" class="panel email-panel"><h2>One-time Postal setup</h2><p class="small muted">Postal provisions its organisation, mail server, sending domain and credentials in its own console. CardShelf manages the connection and application email here.</p><ol class="email-setup-list"><li>Create or select the mail server in Postal, add <strong>cardshelf.cloud</strong> as a sending domain, and publish the DNS records Postal provides.</li><li>Create an API credential for that server. Enter it above with your sender address and save the connection.</li><li>Configure MessageSent, MessageDeliveryFailed and MessageBounced webhooks for the endpoint below. MessageDelayed and MessageHeld are optional. Save the installation’s trusted HTTP signing public key above; CardShelf verifies X-Postal-Signature-256 before updating history.</li><li>Run the DNS checks, enable CardShelf email and send a test to your own administrator account. Review its delivery history and your inbox.</li></ol><label for="email-webhook-endpoint">CardShelf webhook endpoint<input id="email-webhook-endpoint" :value="data.settings.webhook_url" readonly autocomplete="off" spellcheck="false" @focus="($event.target as HTMLInputElement).select()"></label><p class="data-note">DNS changes are made with your DNS provider. Postal’s server provisioning and domain management remain in its console; this page does not modify those records.</p><div class="button-row"><a v-if="setup.provider === 'postal' && postalConsole" :href="postalConsole" target="_blank" rel="noopener noreferrer" class="button secondary">Open Postal console ↗</a></div></section>
      <section id="email-diagnostics" class="panel email-panel"><div class="section-heading"><div><h2>DNS checks</h2><p>Inspect sender records for cardshelf.cloud. Postal server records are checked when Postal is selected.</p></div><button class="button secondary" :disabled="checking || !!busy" @click="checkDns">{{ checking ? 'Checking DNS…' : 'Check DNS' }}</button></div><p v-if="dnsError" class="alert error" role="alert">{{ dnsError }}</p><template v-if="diagnostics"><p class="small muted">Checked {{ date(diagnostics.checked_at) }}</p><div class="email-dns-list"><article v-for="check in diagnostics.checks" :key="check.id"><div><strong>{{ check.label }}</strong><code v-if="check.hostname">{{ check.hostname }}</code><p>{{ check.detail }}</p></div><span class="badge" :class="check.status === 'fail' ? 'red' : check.status === 'warn' ? 'amber' : ''">{{ checkLabels[check.status] || check.status }}</span></article></div><p class="data-note">{{ diagnostics.notice }}</p></template><p v-else class="small muted">Checks run only when requested. Record checks do not guarantee inbox delivery.</p></section>
      <section id="email-delivery" class="panel email-panel"><div class="section-heading"><div><h2>Delivery overview</h2><p>Latest 50 application emails with redacted recipients and delivery status.</p></div></div><div class="email-counts"><span v-for="row in data.counts" :key="row.status" class="badge">{{ statusLabels[row.status] || row.status }}: {{ row.count }}</span><span v-if="!data.counts.length" class="small muted">No email activity yet.</span></div><p class="data-note">Delivery-uncertain messages may already have been accepted and are never retried automatically. Queued or accepted does not mean a message reached an inbox. Signed Postal events update Postal deliveries. SMTP records provider acceptance; inspect your inbox and provider bounce reports separately.</p>
        <form class="email-test-form" @submit.prevent="sendTest"><div><h3>Send a test email</h3><p class="small muted">Sends only to your signed-in administrator account.</p></div><label for="test-admin-password">Administrator password for test<input id="test-admin-password" v-model="testPassword" type="password" required autocomplete="current-password" maxlength="128" :disabled="!!busy"></label><button class="button secondary" :disabled="!!busy || !testPassword || !data.settings.enabled || !data.settings.configured">{{ busy === 'test' ? 'Queuing…' : 'Send test email' }}</button></form>
        <div v-if="data.recent.length" class="table-scroll email-history" role="region" aria-label="Recent email deliveries" tabindex="0"><table><thead><tr><th scope="col">Email</th><th scope="col">Recipient</th><th scope="col">Status</th><th scope="col">Updated</th><th scope="col">Action</th></tr></thead><tbody><tr v-for="row in data.recent" :key="row.id"><td><strong>{{ kindLabels[row.kind] || row.kind }}</strong><small>{{ row.provider === 'smtp' ? 'SMTP' : row.provider === 'postal' ? 'Postal' : 'Provider not recorded' }}</small><small>{{ row.attempts }} attempt{{ row.attempts === 1 ? '' : 's' }}</small></td><td>{{ row.email }}</td><td><span class="badge" :class="['failed', 'bounced'].includes(row.status) ? 'red' : ''">{{ statusLabels[row.status] || row.status }}</span><small v-if="row.last_error">{{ row.last_error }}</small><small v-if="row.sent_with_ssl === true">Recipient TLS confirmed</small><small v-else-if="row.sent_with_ssl === false" class="danger-text">Recipient transport unencrypted</small><small v-else-if="['accepted', 'delivered', 'sent'].includes(row.status)">Recipient TLS not reported</small></td><td>{{ date(row.updated_at || row.created_at) }}</td><td><button v-if="row.can_retry" class="button secondary small-button" :disabled="!!busy" :aria-label="'Review retry for ' + (kindLabels[row.kind] || row.kind) + ' to ' + row.email" @click="selectRetry(row)">Review retry</button><span v-else class="muted">—</span></td></tr></tbody></table></div>
        <p v-else class="empty-inline">Email activity will appear here after a message is queued.</p>
        <form v-if="retryItem" class="email-retry-form" @submit.prevent="retry"><h3>Retry this notification</h3><p class="small">{{ kindLabels[retryItem.kind] || retryItem.kind }} to {{ retryItem.email }}</p><p class="small muted">Only definitively rejected, unaccepted notifications can be retried. Delivery-uncertain messages are held to prevent duplicates. Request a fresh password recovery link through Password recovery.</p><label for="retry-admin-password">Administrator password for retry<input id="retry-admin-password" v-model="retryPassword" type="password" required autocomplete="current-password" maxlength="128" :disabled="!!busy"></label><div class="button-row"><button class="button primary" :disabled="!!busy || !retryPassword">Queue retry</button><button type="button" class="button secondary" :disabled="!!busy" @click="retryItem = null; retryPassword = ''">Cancel</button></div></form>
      </section>
      <section id="email-suppressions" class="panel email-panel"><h2>Suppressed recipients</h2><p class="small muted">Showing the latest 100 suppressions. Suppression prevents email to an address. Review the cause and resolve it before removing a suppression. Removing one does not resend previous messages.</p><div v-if="data.suppressions.length" class="email-suppression-list"><article v-for="row in data.suppressions" :key="row.email"><div><strong>{{ row.email }}</strong><p>{{ row.reason }}</p><small>{{ date(row.created_at) }}</small></div><button class="button secondary small-button" :disabled="!!busy" :aria-label="'Review suppression removal for ' + row.email" @click="reviewSuppression(row)">Review removal</button></article></div><p v-else class="small muted">No recipients are currently suppressed.</p>
        <form id="email-suppression-form" class="form-stack email-suppression-form" @submit.prevent="saveSuppression"><h3>Manage a suppression</h3><div class="email-form-grid"><label for="suppression-email">Recipient email<input id="suppression-email" v-model="suppression.email" type="email" required maxlength="254" autocomplete="off" :disabled="!!busy"></label><label for="suppression-action">Action<select id="suppression-action" v-model="suppression.suppressed" :disabled="!!busy"><option :value="true">Suppress this recipient</option><option :value="false">Remove suppression</option></select></label></div><label for="suppression-reason">Reason<input id="suppression-reason" v-model="suppression.reason" required minlength="5" maxlength="100" :disabled="!!busy" placeholder="What prompted this change?"></label><label for="suppression-password">Administrator password for suppression change<input id="suppression-password" v-model="suppression.password" type="password" required autocomplete="current-password" maxlength="128" :disabled="!!busy"></label><button class="button secondary" :disabled="!!busy || !suppression.password || !suppression.email || suppression.reason.trim().length < 5">{{ suppression.suppressed ? 'Suppress recipient' : 'Remove suppression' }}</button></form>
      </section>
    </template>
    <button v-if="isAdmin && !loading && !data" class="button secondary" @click="load()">Try again</button>
  </main>
